import { test, expect } from '@playwright/test';

test.describe('Order Summary Before Payment Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should display order summary with items and prices', async ({ page }) => {
    // Verify order summary section is visible
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify order items are displayed
    const orderItems = page.getByRole('list', { name: /order items/i });
    await expect(orderItems).toBeVisible();

    // Verify at least one item is shown
    const items = page.getByRole('listitem');
    await expect(items).toHaveCount(1);

    // Verify item details are visible
    const itemName = page.getByText(/product name/i);
    await expect(itemName).toBeVisible();

    const itemPrice = page.getByText(/\$\d+\.\d{2}/);
    await expect(itemPrice).toBeVisible();
  });

  test('should display total amount and breakdown before payment', async ({ page }) => {
    // Verify subtotal is displayed
    const subtotal = page.getByRole('cell', { name: /subtotal/i });
    await expect(subtotal).toBeVisible();

    const subtotalAmount = page.getByText(/subtotal.*\$\d+\.\d{2}/i);
    await expect(subtotalAmount).toBeVisible();

    // Verify tax information is displayed
    const tax = page.getByRole('cell', { name: /tax/i });
    await expect(tax).toBeVisible();

    const taxAmount = page.getByText(/tax.*\$\d+\.\d{2}/i);
    await expect(taxAmount).toBeVisible();

    // Verify shipping cost is displayed
    const shipping = page.getByRole('cell', { name: /shipping/i });
    await expect(shipping).toBeVisible();

    const shippingAmount = page.getByText(/shipping.*\$\d+\.\d{2}/i);
    await expect(shippingAmount).toBeVisible();

    // Verify total amount is prominently displayed
    const totalAmount = page.getByRole('heading', { name: /total/i });
    await expect(totalAmount).toBeVisible();

    const totalPrice = page.getByText(/total.*\$\d+\.\d{2}/i);
    await expect(totalPrice).toBeVisible();
  });

  test('should show confirm payment button only after reviewing summary', async ({ page }) => {
    // Verify order summary is visible
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify confirm payment button is present and enabled
    const confirmButton = page.getByRole('button', { name: /confirm payment|proceed to payment|pay now/i });
    await expect(confirmButton).toBeVisible();
    await expect(confirmButton).toBeEnabled();

    // Verify button is clickable
    await expect(confirmButton).toHaveCount(1);
  });

  test('should allow user to review and modify order before payment', async ({ page }) => {
    // Verify order summary is displayed
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();

    // Verify edit/modify button is available
    const editButton = page.getByRole('button', { name: /edit|modify|change/i });
    await expect(editButton).toBeVisible();

    // Verify back button to cart is available
    const backButton = page.getByRole('link', { name: /back to cart|continue shopping/i });
    await expect(backButton).toBeVisible();

    // Verify all summary details are readable
    const summaryText = await orderSummary.textContent();
    expect(summaryText).toBeTruthy();
    expect(summaryText?.length).toBeGreaterThan(0);
  });
});
